package kotlin.text
inline fun <K> CharSequence.groupBy(keySelector: (Char) -> K): Map<K, List<Char>> { val result = mutableMapOf<K, MutableList<Char>>(); for (item in this) { val key = keySelector(item); val list = result[key]; if (list == null) { val created = mutableListOf<Char>(); result[key] = created; created.add(item) } else list.add(item) }; return result }
inline fun <K, V> CharSequence.groupBy(keySelector: (Char) -> K, valueTransform: (Char) -> V): Map<K, List<V>> { val result = mutableMapOf<K, MutableList<V>>(); for (item in this) { val key = keySelector(item); var list = result[key]; if (list == null) { list = mutableListOf<V>(); result[key] = list }; list.add(valueTransform(item)) }; return result }
inline fun <K, V> CharSequence.associate(transform: (Char) -> Pair<K, V>): Map<K, V> { val result = mutableMapOf<K, V>(); for (item in this) { val pair = transform(item); result[pair.first] = pair.second }; return result }
inline fun <K> CharSequence.associateBy(keySelector: (Char) -> K): Map<K, Char> { val result = mutableMapOf<K, Char>(); for (item in this) result[keySelector(item)] = item; return result }
inline fun <K, V> CharSequence.associateBy(keySelector: (Char) -> K, valueTransform: (Char) -> V): Map<K, V> { val result = mutableMapOf<K, V>(); for (item in this) { val key = keySelector(item); result[key] = valueTransform(item) }; return result }
inline fun <V> CharSequence.associateWith(valueSelector: (Char) -> V): Map<Char, V> { val result = mutableMapOf<Char, V>(); for (item in this) result[item] = valueSelector(item); return result }
inline fun CharSequence.partition(predicate: (Char) -> Boolean): Pair<CharSequence, CharSequence> { val yes = StringBuilder(); val no = StringBuilder(); for (item in this) { if (predicate(item)) yes.append(item) else no.append(item) }; return Pair(yes, no) }
inline fun String.partition(predicate: (Char) -> Boolean): Pair<String, String> { val yes = StringBuilder(); val no = StringBuilder(); for (item in this) { if (predicate(item)) yes.append(item) else no.append(item) }; return Pair(yes.toString(), no.toString()) }
inline infix fun CharSequence.zip(other: CharSequence): List<Pair<Char, Char>> { val result = mutableListOf<Pair<Char, Char>>(); val leftSize = this.length; val rightSize = other.length; val size = if (leftSize < rightSize) leftSize else rightSize; var index = 0; while (index < size) { val left = this[index]; val right = other[index]; index++; result.add(Pair(left, right)) }; return result }
inline fun <V> CharSequence.zip(other: CharSequence, transform: (Char, Char) -> V): List<V> { val result = mutableListOf<V>(); val leftSize = this.length; val rightSize = other.length; val size = if (leftSize < rightSize) leftSize else rightSize; var index = 0; while (index < size) { val left = this[index]; val right = other[index]; index++; result.add(transform(left, right)) }; return result }
